{"command":"create","path":"/workspace/source/packages/privacy/src/erasure.ts","file_text":"import { createHash } from 'node:crypto';
import type pg from 'pg';
import { Redis } from 'ioredis';
import { config } from '../../config/src/index.js';
import { pool, transaction } from '../../database/src/pool.js';
import { deleteMailpitMessagesForRecipient } from '../../notifications/src/mailpit.js';
import { CUSTOMER_INDEX, searchClient } from '../../search/src/client.js';
import { DOCUMENT_BUCKET, objectStore } from '../../storage/src/minio.js';
import {
  ERASED_CUSTOMER_NAME,
  emailHash,
  erasedEmail,
  erasedExternalReference,
  scrubPayload,
  toErasureRequestView,
  type ErasureRequestRow,
  type ErasureRequestView,
} from './scrub.js';

const IDEMPOTENCY_SCOPE = 'customer-erasure';
export const ERASURE_JOB_TYPE = 'customer.erasure';
export const ERASURE_QUEUE = 'privacy';

function httpError(statusCode: number, message: string): Error {
  return Object.assign(new Error(message), { statusCode });
}

export async function getErasureRequest(merchantId: string, requestId: string): Promise<ErasureRequestView | undefined> {
  const result = await pool.query<ErasureRequestRow>(
    `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND id=$2`,
    [merchantId, requestId],
  );
  return result.rows[0] ? toErasureRequestView(result.rows[0]) : undefined;
}

async function enqueueErasureJob(client: pg.PoolClient, request: ErasureRequestRow): Promise<void> {
  await client.query(
    `INSERT INTO operations.jobs(queue,job_type,merchant_id,payload)
     VALUES($1,$2,$3,$4)`,
    [ERASURE_QUEUE, ERASURE_JOB_TYPE, request.merchant_id, { requestId: request.id }],
  );
}

/**
 * Starts a data deletion request, or returns the existing one when the idempotency key
 * or the customer already has one. Reusing a key for a different customer conflicts.
 */
export async function createOrResumeErasureRequest(
  merchantId: string,
  customerId: string,
  idempotencyKey: string,
): Promise<ErasureRequestView> {
  return await transaction(async (client) => {
    const customer = await client.query<{ id: string }>(
      `SELECT id FROM customers.customers WHERE merchant_id=$1 AND id=$2 FOR UPDATE`,
      [merchantId, customerId],
    );
    if (!customer.rows[0]) throw httpError(404, 'customer_not_found');

    const keyHash = createHash('sha256').update(idempotencyKey).digest('hex');
    const replay = await client.query<{ request_hash: string; response_body: { requestId?: string } | null }>(
      `SELECT request_hash,response_body FROM operations.idempotency_keys
       WHERE merchant_id=$1 AND scope=$2 AND key=$3 FOR UPDATE`,
      [merchantId, IDEMPOTENCY_SCOPE, keyHash],
    );
    if (replay.rows[0] && replay.rows[0].request_hash !== customerId) {
      throw httpError(409, 'idempotency_key_reused_for_different_customer');
    }
    if (replay.rows[0]?.response_body?.requestId) {
      const existing = await client.query<ErasureRequestRow>(
        `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND id=$2`,
        [merchantId, replay.rows[0].response_body.requestId],
      );
      if (existing.rows[0]) return toErasureRequestView(existing.rows[0]);
    }

    const existing = await client.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND customer_id=$2 FOR UPDATE`,
      [merchantId, customerId],
    );
    if (existing.rows[0]) {
      const request = existing.rows[0];
      await client.query(
        `INSERT INTO operations.idempotency_keys(merchant_id,scope,key,request_hash,response_status,response_body,expires_at)
         VALUES($1,$2,$3,$4,202,$5,now()+interval '30 days') ON CONFLICT DO NOTHING`,
        [merchantId, IDEMPOTENCY_SCOPE, keyHash, customerId, { requestId: request.id }],
      );
      if (request.status === 'failed') await enqueueErasureJob(client, request);
      return toErasureRequestView(request);
    }

    const created = await client.query<ErasureRequestRow>(
      `INSERT INTO customers.erasure_requests(merchant_id,customer_id,idempotency_key)
       VALUES($1,$2,$3) RETURNING *`,
      [merchantId, customerId, idempotencyKey],
    );
    const request = created.rows[0]!;
    await client.query(
      `INSERT INTO operations.idempotency_keys(merchant_id,scope,key,request_hash,response_status,response_body,expires_at)
       VALUES($1,$2,$3,$4,202,$5,now()+interval '30 days') ON CONFLICT DO NOTHING`,
      [merchantId, IDEMPOTENCY_SCOPE, keyHash, customerId, { requestId: request.id }],
    );
    await enqueueErasureJob(client, request);
    await client.query(
      `INSERT INTO platform.audit_logs(merchant_id,actor_type,target_type,target_id,action,metadata,correlation_id)
       VALUES($1,'api_key','customer',$2,'customer.erasure.requested',$3,gen_random_uuid())`,
      [merchantId, customerId, { requestId: request.id }],
    );
    return toErasureRequestView(request);
  });
}

interface ErasureContext {
  request: ErasureRequestRow;
  originalEmail: string;
  receiptChecksums: { objectKey: string; checksum: string }[];
  invoiceObjectKeys: string[];
}

async function getObjectBody(objectKey: string): Promise<string> {
  const stream = await objectStore.getObject(DOCUMENT_BUCKET, objectKey);
  const chunks: Buffer[] = [];
  for await (const chunk of stream) chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
  return Buffer.concat(chunks).toString('utf8');
}

/** Removes customer personal data from every operational table. Idempotent by design. */
async function scrubDatabase(client: pg.PoolClient, context: ErasureContext): Promise<void> {
  const { request } = context;
  const merchantId = request.merchant_id;
  const customerId = request.customer_id;

  await client.query(
    `INSERT INTO customers.erased_customers(merchant_id,customer_id,email_hash)
     VALUES($1,$2,$3) ON CONFLICT DO NOTHING`,
    [merchantId, customerId, emailHash(context.originalEmail)],
  );
  await client.query(
    `UPDATE customers.customers
     SET external_reference=$3,email=$4,name=$5,phone=NULL,metadata='{}',status='erased',
         version=version+1,updated_at=now()
     WHERE merchant_id=$1 AND id=$2`,
    [merchantId, customerId, erasedExternalReference(customerId), erasedEmail(customerId), ERASED_CUSTOMER_NAME],
  );
  await client.query(`DELETE FROM customers.addresses WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
  await client.query(`DELETE FROM customers.contacts WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
  await client.query(
    `UPDATE customers.payment_method_refs
     SET provider_token='erased',brand=NULL,last4=NULL,billing_name=NULL,billing_address=NULL,status='erased'
     WHERE merchant_id=$1 AND customer_id=$2`,
    [merchantId, customerId],
  );
  await client.query(
    `DELETE FROM customers.provider_customer_mappings WHERE merchant_id=$1 AND customer_id=$2`,
    [merchantId, customerId],
  );
  await client.query(
    `DELETE FROM provider_sandbox.customers WHERE merchant_id=$1 AND payflow_customer_id=$2`,
    [merchantId, customerId],
  );
  await client.query(
    `DELETE FROM customers.support_participants WHERE customer_id=$1
       AND ticket_id IN (SELECT id FROM customers.support_tickets WHERE merchant_id=$2)`,
    [customerId, merchantId],
  );
  await client.query(
    `UPDATE customers.support_messages SET author_id=NULL,body='[deleted]',attachments='[]'
     WHERE merchant_id=$1 AND author_type='customer' AND author_id=$2`,
    [merchantId, customerId],
  );
  await client.query(
    `UPDATE payments.payment_intents SET customer_snapshot='{}',description=NULL,updated_at=now()
     WHERE merchant_id=$1 AND customer_id=$2`,
    [merchantId, customerId],
  );
  const attempts = await client.query<{ id: string; request_payload: unknown; response_payload: unknown }>(
    `SELECT a.id,a.request_payload,a.response_payload FROM payments.payment_attempts a
     JOIN payments.payment_intents p ON p.id=a.payment_intent_id
     WHERE p.merchant_id=$1 AND p.customer_id=$2`,
    [merchantId, customerId],
  );
  for (const attempt of attempts.rows) {
    await client.query(
      `UPDATE payments.payment_attempts SET request_payload=$2,response_payload=$3 WHERE id=$1`,
      [attempt.id, scrubPayload(attempt.request_payload), attempt.response_payload === null ? null : scrubPayload(attempt.response_payload)],
    );
  }
  await client.query(
    `UPDATE payments.refunds SET customer_email=NULL
     WHERE merchant_id=$1 AND payment_intent_id IN
       (SELECT id FROM payments.payment_intents WHERE merchant_id=$1 AND customer_id=$2)`,
    [merchantId, customerId],
  );
  const invoices = await client.query<{ id: string; object_key: string | null }>(
    `UPDATE payments.invoices SET billing_snapshot='{}',object_key=NULL
     WHERE merchant_id=$1 AND customer_id=$2 RETURNING id,object_key`,
    [merchantId, customerId],
  );
  context.invoiceObjectKeys = invoices.rows.map((row) => row.object_key).filter((key): key is string => Boolean(key));
  await client.query(
    `DELETE FROM operations.analytics_events WHERE merchant_id=$1 AND (customer_id=$2 OR email=$3)`,
    [merchantId, customerId, context.originalEmail],
  );
  await client.query(
    `DELETE FROM operations.notification_preferences WHERE merchant_id=$1 AND customer_id=$2`,
    [merchantId, customerId],
  );
  await client.query(
    `DELETE FROM operations.notifications WHERE merchant_id=$1 AND customer_id=$2`,
    [merchantId, customerId],
  );
  await client.query(
    `DELETE FROM operations.email_deliveries WHERE merchant_id=$1 AND customer_id=$2`,
    [merchantId, customerId],
  );
  await client.query(
    `UPDATE platform.audit_logs SET metadata='{}'
     WHERE merchant_id=$1 AND target_type='customer' AND target_id=$2`,
    [merchantId, customerId],
  );

  const outbox = await client.query<{ id: string; payload: unknown }>(
    `SELECT id,payload FROM operations.outbox_events
     WHERE merchant_id=$1 AND status='pending' AND (
       (aggregate_type='customer' AND aggregate_id=$2) OR payload->>'customerId'=$2
     )`,
    [merchantId, customerId],
  );
  for (const event of outbox.rows) {
    await client.query(`UPDATE operations.outbox_events SET payload=$2 WHERE id=$1`, [event.id, scrubPayload(event.payload)]);
  }
  const pendingJobs = await client.query<{ id: string; payload: unknown }>(
    `SELECT id,payload FROM operations.jobs
     WHERE merchant_id=$1 AND status IN ('pending','retry') AND payload->>'customerId'=$2`,
    [merchantId, customerId],
  );
  for (const job of pendingJobs.rows) {
    await client.query(`UPDATE operations.jobs SET payload=$2 WHERE id=$1`, [job.id, scrubPayload(job.payload)]);
  }

  const receipts = await client.query<{ object_key: string }>(
    `SELECT object_key FROM operations.document_manifests
     WHERE merchant_id=$1 AND customer_id=$2 AND document_type='receipt'`,
    [merchantId, customerId],
  );
  for (const receipt of receipts.rows) {
    const body = await getObjectBody(receipt.object_key);
    const scrubbed = JSON.stringify(scrubPayload(JSON.parse(body)));
    await objectStore.putObject(DOCUMENT_BUCKET, receipt.object_key, scrubbed, Buffer.byteLength(scrubbed), {
      'Content-Type': 'application/json',
    });
    context.receiptChecksums.push({
      objectKey: receipt.object_key,
      checksum: createHash('sha256').update(scrubbed).digest('hex'),
    });
  }
  await client.query(
    `UPDATE operations.document_manifests SET metadata=metadata-'email'-'name'-'phone'-'customerEmail'
     WHERE merchant_id=$1 AND customer_id=$2`,
    [merchantId, customerId],
  );
}

async function scrubExternalSystems(context: ErasureContext): Promise<void> {
  const { request } = context;
  const settings = config();
  const document = {
    merchantId: request.merchant_id,
    customerId: request.customer_id,
    email: erasedEmail(request.customer_id),
    name: ERASED_CUSTOMER_NAME,
    phone: null,
    updatedAt: new Date().toISOString(),
  };
  await searchClient.index({
    index: CUSTOMER_INDEX,
    id: `${request.merchant_id}:${request.customer_id}`,
    body: document,
    refresh: true,
  });
  const redis = new Redis(settings.REDIS_URL);
  try {
    const cacheKey = `merchant:${request.merchant_id}:customer:${request.customer_id}`;
    await redis.set(cacheKey, JSON.stringify(document), 'EX', 3600);
    await redis.del(`${cacheKey}:activity`);
  } finally {
    await redis.quit();
  }
  await deleteMailpitMessagesForRecipient(context.originalEmail);
  for (const objectKey of context.invoiceObjectKeys) {
    await objectStore.removeObject(DOCUMENT_BUCKET, objectKey);
  }
}

/** Runs one erasure attempt. Safe to repeat: every step converges on the same end state. */
export async function executeErasure(requestId: string): Promise<void> {
  const context: ErasureContext = {
    request: undefined as unknown as ErasureRequestRow,
    originalEmail: '',
    receiptChecksums: [],
    invoiceObjectKeys: [],
  };
  const shouldRun = await transaction(async (client) => {
    const result = await client.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE id=$1 FOR UPDATE`,
      [requestId],
    );
    const request = result.rows[0];
    if (!request) throw new Error(`erasure request ${requestId} not found`);
    if (request.status === 'completed') return false;
    context.request = request;
    const customer = await client.query<{ email: string }>(
      `SELECT email FROM customers.customers WHERE merchant_id=$1 AND id=$2`,
      [request.merchant_id, request.customer_id],
    );
    if (!customer.rows[0]) throw new Error('erasure_customer_missing');
    context.originalEmail = customer.rows[0].email;
    await client.query(
      `UPDATE customers.erasure_requests
       SET status='processing',attempts=attempts+1,last_error=NULL,updated_at=now() WHERE id=$1`,
      [requestId],
    );
    return true;
  });
  if (!shouldRun) return;

  try {
    await transaction(async (client) => await scrubDatabase(client, context));
  } catch (error) {
    await markErasureFailed(requestId, 'erasure_database_failed', error);
    throw error;
  }
  try {
    await scrubExternalSystems(context);
  } catch (error) {
    await markErasureFailed(requestId, 'erasure_external_system_failed', error);
    throw error;
  }
  await transaction(async (client) => {
    for (const receipt of context.receiptChecksums) {
      await client.query(
        `UPDATE operations.document_manifests SET checksum=$3 WHERE merchant_id=$1 AND object_key=$2`,
        [context.request.merchant_id, receipt.objectKey, receipt.checksum],
      );
    }
    await client.query(
      `DELETE FROM operations.document_manifests
       WHERE merchant_id=$1 AND object_key=ANY($2)`,
      [context.request.merchant_id, context.invoiceObjectKeys],
    );
    await client.query(
      `UPDATE customers.erasure_requests
       SET status='completed',last_error=NULL,updated_at=now(),completed_at=now()
       WHERE id=$1 AND status<>'completed'`,
      [requestId],
    );
  });
}

async function markErasureFailed(requestId: string, code: string, error: unknown): Promise<void> {
  await pool.query(
    `UPDATE customers.erasure_requests SET status='failed',last_error=$2,updated_at=now() WHERE id=$1`,
    [requestId, code],
  );
  void error;
}
"}

