    if (job.job_type !== ERASURE_JOB_TYPE) {
      await transaction(async (client) => await completeJob(client, job));
      continue;
    }
    try {
      await executeErasure(job.payload.requestId);
      await transaction(async (client) => await completeJob(client, job));
    } catch (error) {
      logger.error({ error, jobId: job.id, requestId: job.payload.requestId }, 'erasure job failed');
      await transaction(async (client) => await failJob(client, job, error));
    }
  }
}

