test('scrubPayload removes personal data keys recursively and keeps financial facts', () => {
  const payload = {
    paymentId: randomUUID(),
    customerId: randomUUID(),
    amount: 500,
    currency: 'USD',
    customerEmail: 'person@example.test',
    customerSnapshot: { email: 'person@example.test', name: 'Person', nested: { phone: '123' } },
    lines: [{ description: 'seat', total: 500, billingName: 'Person' }],
  };
  const scrubbed = scrubPayload(payload) as Record<string, unknown>;
  assert.equal(scrubbed.amount, 500);
  assert.equal(scrubbed.currency, 'USD');
  assert.ok(!('customerEmail' in scrubbed));
  assert.ok(!('customerSnapshot' in scrubbed));
  const lines = scrubbed.lines as Record<string, unknown>[];
  assert.equal(lines[0]!.total, 500);
  assert.ok(!('billingName' in lines[0]!));
  assert.ok(!('description' in lines[0]!));
});

test('scrubPayload leaves scalars and non-PII objects untouched', () => {
  assert.equal(scrubPayload('x'), 'x');
  assert.equal(scrubPayload(null), null);
  assert.deepEqual(scrubPayload({ status: 'succeeded', attempts: 2 }), { status: 'succeeded', attempts: 2 });
});

test('erased identities are deterministic and contain no original personal data', () => {
  const customerId = randomUUID();
  assert.equal(erasedEmail(customerId), `erased-${customerId}@erased.invalid`);
  assert.equal(erasedExternalReference(customerId), `erased-${customerId}`);
  assert.equal(ERASED_CUSTOMER_NAME, 'Erased customer');
